\begin{gather}
    \label{eq: Resource allocation problem}
    \begin{aligned}
        \min_{\boldsymbol{\theta} \in (\mathbb{R}^{n})^{m}} \quad & F(\boldsymbol{\theta}) \triangleq \sum_{i=1}^{m} f_{i}(\boldsymbol{\theta}_{i})\\
        \text{subject to} \quad & \sum_{i=1}^{m} \boldsymbol{\theta}_{i} = \mathbf{r},
    \end{aligned}
\end{gather}

\label{ass: Lipschitz}
    Each $f_{i}$ in \eqref{eq: Resource allocation problem} is both $L_{f_{i}}^{g}$-gradient Lipschitz and $L_{f_{i}}^{H}$-Hessian Lipschitz, i.e., for all $\boldsymbol{\theta}_{i},\boldsymbol{\omega}_{i}\in\mathbb{R}^{n}$ and each $i \in \mathcal{V}$,
    \begin{align*}
        \|\nabla f_{i}(\boldsymbol{\theta}_{i}) - \nabla f_{i}(\boldsymbol{\omega}_{i})\|
        &\le L_{f_{i}}^{g} \|\boldsymbol{\theta}_{i}-\boldsymbol{\omega}_{i}\|,\\
        \|\nabla^{2} f_{i}(\boldsymbol{\theta}_{i}) - \nabla^{2} f_{i}(\boldsymbol{\omega}_{i})\|
        &\le L_{f_{i}}^{H} \|\boldsymbol{\theta}_{i}-\boldsymbol{\omega}_{i}\|.
    \end{align*}

\begin{align*}
        \|\nabla f_{i}(\boldsymbol{\theta}_{i}) - \nabla f_{i}(\boldsymbol{\omega}_{i})\|
        &\le L_{f_{i}}^{g} \|\boldsymbol{\theta}_{i}-\boldsymbol{\omega}_{i}\|,\\
        \|\nabla^{2} f_{i}(\boldsymbol{\theta}_{i}) - \nabla^{2} f_{i}(\boldsymbol{\omega}_{i})\|
        &\le L_{f_{i}}^{H} \|\boldsymbol{\theta}_{i}-\boldsymbol{\omega}_{i}\|.
    \end{align*}

If Assumption \ref{ass: Lipschitz} holds, then $F$ defined in \eqref{eq: Resource allocation problem} has $L_{F}^{g}$-Lipschitz continuous gradient and $L_{F}^{H}$-Lipschitz continuous Hessian with
\begin{gather}
\label{eq: Lipschitz continuous for F}
    L_{F}^{g} = \max_{i} \{L_{f_{i}}^{g}\},~L_{F}^{H} = \max_{i} \{L_{f_{i}}^{H}\}.
\end{gather}
If Assumption \ref{ass: Coercivity} holds, then $F$ defined in \eqref{eq: Resource allocation problem} is also coercive.

\label{pro: Same sequence}
    Let auxiliary function
    \begin{gather}
        \begin{gathered}
            \label{eq: Auxiliary function}
            \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}) \triangleq F(\boldsymbol{\theta}^{0} + \sqrt{\hat{\mathbf{L}}} \mathbf{x}).
        \end{gathered}    
    \end{gather}
    For the distributed resource allocation problem in \eqref{eq: Resource allocation problem}, given fixed step-size $\alpha > 0$ and initial point $\boldsymbol{\theta}^{0} \in (\mathbb{R}^{n})^{m}$ satisfying $\bm{1}_{m}^{\top} \otimes \mathbf{I}_{n} \cdot \boldsymbol{\theta}^{0} = \bm{r}$, the sequence $\{\boldsymbol{\theta}^{k}\}$ generated by \eqref{eq: LGD aggregate form} is equivalent to the sequence generated by applying gradient descent to $\Psi_{\boldsymbol{\theta}^{0}}$ from the same initial point $\boldsymbol{\theta}^{0} \in (\mathbb{R}^{n})^{m}$ and $\mathbf{x}^{0} = \bm{0} \in (\mathbb{R}^{n})^{m}$ with the same fixed step-size $\alpha > 0$, as per
    \begin{gather}
    \label{eq: LGD with auxiliary function}
        \begin{gathered}
            \mathbf{x}^{k+1} = \mathbf{x}^{k} - \alpha \nabla \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k}),\\
            \boldsymbol{\theta}^{k+1} = \boldsymbol{\theta}^{0} + \sqrt{\hat{\mathbf{L}}} \mathbf{x}^{k+1}.
        \end{gathered}
    \end{gather}

If Assumption \ref{ass: Lipschitz} holds, then $\Psi_{\boldsymbol{\theta}^{0}}$ in \eqref{eq: Auxiliary function} has $L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}$-Lipschitz continuous gradient and $L_{\Psi_{\boldsymbol{\theta}^{0}}}^{H}$-Lipschitz continuous Hessian with
\begin{gather}
\label{eq: Psi Lipschitz}
    L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g} = \norm{\sqrt{\mathbf{L}}}^{2} \cdot L_{F}^{g},~L_{\Psi_{\boldsymbol{\theta}^{0}}}^{H} =  \norm{\sqrt{\mathbf{L}}}^{3} \cdot L_{F}^{H}.
\end{gather}

\label{def: first-order stationary point}
    For the distributed resource allocation problem in \eqref{eq: Resource allocation problem}, a point $\boldsymbol{\theta} \in (\mathbb{R}^{n})^{m}$ is said to be a first-order stationary point if it satisfies the following:
    \begin{enumerate}

        \item $\sqrt{\hat{\mathbf{L}}} \cdot \nabla F(\boldsymbol{\theta}) = 0$;
        \item $\bm{1}_{m}^{\top} \otimes \mathbf{I}_{n} \cdot \boldsymbol{\theta} = \bm{r}$,
    \end{enumerate}
    where $\sqrt{\hat{\mathbf{L}}} = \sqrt{\mathbf{L}}\otimes \mathbf{I}_{n}$ with $\sqrt{\mathbf{L}} \cdot \sqrt{\mathbf{L}} = \mathbf{L}$.

\label{pro: First order property}
    Let Assumptions \ref{ass: Lipschitz}, \ref{ass: Coercivity} and \ref{ass: Network} hold. Given initial point $\boldsymbol{\theta}^{0} \in (\mathbb{R}^{n})^{m}$ satisfying $\bm{1}_{m}^{\top} \otimes \mathbf{I}_{n} \cdot \boldsymbol{\theta}^{0} = \bm{r}$, for any fixed step-size
    \begin{gather*}
        0 < \alpha \le \frac{1}{\|\sqrt{\mathbf{L}}\|^{2} \cdot L_{F}^{g}},
    \end{gather*}
    the sequence $\{\boldsymbol{\theta}^{k}\}$ generated by \eqref{eq: LGD aggregate form} satisfies that for all $k \ge 0$, $\bm{1}_{m}^{\top} \otimes \mathbf{I}_{n} \cdot \boldsymbol{\theta}^{k}= \bm{r}$ and
    \begin{gather*}
        \lim_{k\rightarrow\infty} \norm{\sqrt{\hat{\mathbf{L}}} \cdot \nabla F(\boldsymbol{\theta}^{k})} = 0.
    \end{gather*}

\label{pro: Second order relations}
    Let Assumption \ref{ass: Network} hold. For the distributed resource allocation problem in \eqref{eq: Resource allocation problem}, given an initial point $\boldsymbol{\theta}^{0} \in (\mathbb{R}^{n})^{m}$ satisfying $\bm{1}_{m}^{\top} \otimes \mathbf{I}_{n} \cdot \boldsymbol{\theta}^{0} = \bm{r}$, if the following holds at $\mathbf{x} \in (\mathbb{R}^{n})^{m}$:
    \begin{enumerate}

        \item $\|\nabla \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x})\| \le \epsilon$;

        \item $\lambda_{\min} (\nabla^{2} \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x})) \ge -\gamma$,
    \end{enumerate}
    then, $\boldsymbol{\theta} = \boldsymbol{\theta}^{0} + \sqrt{\hat{\mathbf{L}}} \mathbf{x}$ is an $(\epsilon,\gamma/\lambda_{\min}^{+}(\mathbf{L}))$-second-order stationary point of Problem \eqref{eq: Resource allocation problem}, where $\Psi_{\boldsymbol{\theta}^{0}}$ is defined in \eqref{eq: Auxiliary function} and $\sqrt{\hat{\mathbf{L}}} = \sqrt{\mathbf{L}}\otimes \mathbf{I}_{n}$ with $\sqrt{\mathbf{L}} \cdot \sqrt{\mathbf{L}} = \mathbf{L}$.

\caption{Noisy Laplacian Gradient Descent (NLGD)}
\label{alg:NLGD}
\begin{algorithmic}[1]
\REQUIRE Feasible $\boldsymbol{\theta}_{i}^{0}$, $\alpha$, $\{\ell_{ij},\tilde{\ell}_{ij}\}_{j=1}^{m}$, $\sigma^{2}$, and shared seed $s$
\FOR{$k = 0,1,2,\dots$}
    \FORALL{agents $i \in \mathcal{V}$}
        \STATE Exchange $\nabla f_i(\boldsymbol{\theta}_{i}^{k})$ with neighboring agents $j$ satisfying $\ell_{ij}\neq 0$
        \STATE Generate perturbations $\mathbf{n}_j^k = \mathrm{PRNG}(s,k,j)$ for all $j \in \mathcal{V}$ using a common pseudo-random generator with shared seed $s$
        \STATE Compute $\boldsymbol{\theta}_{i}^{k+1}$ using \eqref{eq: NLGD}
    \ENDFOR
\ENDFOR
\end{algorithmic}

\label{pro: NGD interpretation}
Let $\Psi_{\boldsymbol{\theta}^{0}}$ be defined in \eqref{eq: Auxiliary function}. For any $\alpha>0$, feasible $\boldsymbol{\theta}^{0}$ satisfying $\bm{1}_{m}^{\top}\otimes\mathbf{I}_{n}\cdot\boldsymbol{\theta}^{0}=\mathbf{r}$, and perturbation sequence $\{\mathbf{n}^{k}\}$, the sequence $\{\boldsymbol{\theta}^{k}\}$ generated by \eqref{eq: NLGD aggregate form} is equivalently generated from $\mathbf{x}^{0}=\bm{0}$ by
\begin{subequations}
\label{eq: NLGD with auxiliary function}
\begin{align}
\mathbf{x}^{k+1}&=\mathbf{x}^{k}-\alpha\left(\nabla\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k})+\mathbf{n}^{k}\right), \label{eq: NLGD with auxiliary function 1}\\
\boldsymbol{\theta}^{k+1}&=\boldsymbol{\theta}^{0}+\sqrt{\hat{\mathbf{L}}}\mathbf{x}^{k+1}. \label{eq: NLGD with auxiliary function 2}
\end{align}
\end{subequations}

\begin{align}
\mathbf{x}^{k+1}&=\mathbf{x}^{k}-\alpha\left(\nabla\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k})+\mathbf{n}^{k}\right), \label{eq: NLGD with auxiliary function 1}\\
\boldsymbol{\theta}^{k+1}&=\boldsymbol{\theta}^{0}+\sqrt{\hat{\mathbf{L}}}\mathbf{x}^{k+1}. \label{eq: NLGD with auxiliary function 2}
\end{align}

\label{pro: Approximate second order}
    Let Assumptions \ref{ass: Lipschitz}, \ref{ass: Coercivity}, \ref{ass: Network} and \ref{ass: Random perturbation} hold. Further, let $f_{i}^{\star}$ denote the global minimum of function $f_{i}$ for $i\in\mathcal{V}$. Then, given parameter $\epsilon_{g} > 0$, $\epsilon_{H} = \sqrt{\epsilon_{g}L_{\Psi_{\boldsymbol{\theta}^{0}}}^{H}}$, and confidence parameter $0 < p < 1$ with $L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g},L_{\Psi_{\boldsymbol{\theta}^{0}}}^{H}$ as per \eqref{eq: Psi Lipschitz}, there exists
    \begin{gather}
    \label{eq: alpha bar}
        \bar{\alpha} \le \min\{\frac{1}{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}},~-\frac{2\ln{(p)}}{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}}\}
    \end{gather}
    such that for any step-size $\alpha \le \bar{\alpha}$, with random perturbation variance
    \begin{gather}
    \label{eq: Variance}
        \sigma^{2}=\frac{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}\alpha\epsilon_{g}^{2}}{12mn},
    \end{gather}
    and initial condition satisfying $\bm{1}_{m}^{\top} \otimes \mathbf{I}_{n} \cdot \boldsymbol{\theta}^{0} = \bm{r}$ and $\mathbf{x}^{0} = \bm{0}$, after
    \begin{gather}
    \label{eq: Iteration}
        K = \lceil \frac{\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{0}) - \sum_{i=1}^{m} f_{i}^{\star}}{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g} \epsilon_{g}^{2} \alpha^{2}} \rceil
    \end{gather}
    iterations of \eqref{eq: NLGD with auxiliary function}, it follows that
    \begin{gather}
    \label{eq: Approximate second order}
        \mathbb{P} \Bigg[\exists k \in [0,K],~\|\nabla \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k})\| \le\epsilon_{g}~~\land~~\lambda_{\min} (\nabla^{2} \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k})) \ge -\epsilon_{H}
        \Bigg] \ge 1 - p.
    \end{gather}

\label{the: Approximate second order}
    Let Assumptions \ref{ass: Lipschitz}, \ref{ass: Coercivity}, \ref{ass: Network} and \ref{ass: Random perturbation} hold. Further, let $f_{i}^{\star}$ denote the global minimum of function $f_{i}$ for $i\in\mathcal{V}$. Then, given parameters $\epsilon_{g} > 0$, and $\epsilon_{H} = \sqrt{\epsilon_{g} \cdot\|\sqrt{\mathbf{L}}\|^{3} \cdot L_{F}^{H}}$, and confidence parameter $0 < p < 1$ with $L_{F}^{g},L_{F}^{H}$ as per \eqref{eq: Lipschitz continuous for F}, there exists
    \begin{gather*}
        \bar{\alpha} \le \min\{\frac{1}{\|\sqrt{\mathbf{L}}\|^{2} \cdot L_{F}^{g}},~-\frac{2\ln{(p)}}{\|\sqrt{\mathbf{L}}\|^{2} \cdot L_{F}^{g}}\}
    \end{gather*}
    such that for any step-size $\alpha \le \bar{\alpha}$, with random perturbation
    variance $\sigma^{2}$ as per \eqref{eq: Variance}, $K$ as per \eqref{eq: Iteration}, $\{\boldsymbol{\theta}^{k}\}$ given by \eqref{eq: NLGD} with an initial point $\boldsymbol{\theta}^{0} \in (\mathbb{R}^{n})^{m}$ satisfying $\bm{1}_{m}^{\top} \otimes \mathbf{I}_{n} \cdot \boldsymbol{\theta}^{0} = \bm{r}$, within $K$ iterations of \eqref{eq: NLGD}, with probability $1-p$, there exists an $(\epsilon_{g},\epsilon_{H}/\lambda_{\min}^{+}(\mathbf{L}))$-second-order stationary point of Problem \eqref{eq: Resource allocation problem}, i.e.,
    \begin{multline*}
        \mathbb{P} \Bigg[\exists k \in [0,K],~\|\sqrt{\hat{\mathbf{L}}} \cdot \nabla F(\boldsymbol{\theta}^{k})\| \le\epsilon_{g}\\
        \land~~\forall~\mathbf{d} \in \mathcal{T},~\mathbf{d}^{\top} \nabla^{2} F(\boldsymbol{\theta}^{k}) \mathbf{d} \ge - \frac{\epsilon_{H}}{\lambda_{\min}^{+}(\mathbf{L})} \norm{\mathbf{d}}^{2}\\
        \land~~\bm{1}_{m}^{\top} \otimes \mathbf{I}_{n} \cdot \boldsymbol{\theta}^{k} = \bm{r}\Bigg] \ge 1 - p,
    \end{multline*}
     where $\sqrt{\hat{\mathbf{L}}} = \sqrt{\mathbf{L}}\otimes \mathbf{I}_{n}$ with Laplacian matrix $\mathbf{L} = \sqrt{\mathbf{L}} \cdot \sqrt{\mathbf{L}}$ and tangent space $\mathcal{T} = \{\mathbf{d} \in (\mathbb{R}^{n})^{m}~:~\bm{1}_{m}^{\top} \otimes \mathbf{I}_{n} \cdot \mathbf{d} = \bm{0}\}$. Moreover, if the initial point $\boldsymbol{\theta}^{0}$ is feasible, i.e., $\bm{1}_{m}^{\top} \otimes \mathbf{I}_{n} \cdot \boldsymbol{\theta}^{0} = \bm{r}$, then the feasibility condition $\bm{1}_{m}^{\top} \otimes \mathbf{I}_{n} \cdot \boldsymbol{\theta}^{k} = \bm{r}$ holds for all $k \ge 0$ due to the Laplacian structure of~\eqref{eq: NLGD}, ensuring \emph{anytime feasibility} of the allocation.

By the definition of $\Psi_{\boldsymbol{\theta}^{0}}$ in \eqref{eq: Auxiliary function},
\begin{gather}
\label{eq: Psi gradient}
   \nabla \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k}) = \sqrt{\hat{\mathbf{L}}} \cdot \nabla F(\boldsymbol{\theta}^{0} + \sqrt{\hat{\mathbf{L}}} \mathbf{x}^{k}) = \sqrt{\hat{\mathbf{L}}} \cdot \nabla F(\boldsymbol{\theta}^{k}).
\end{gather}
Thus, the update in \eqref{eq: LGD with auxiliary function} can be reformulated as
\begin{gather*}
    \mathbf{x}^{k+1} = \mathbf{x}^{k} - \alpha \nabla \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k}) = \mathbf{x}^{k} - \alpha \sqrt{\hat{\mathbf{L}}} \cdot \nabla F(\boldsymbol{\theta}^{0} + \sqrt{\hat{\mathbf{L}}} \mathbf{x}^{k}),\\
    \boldsymbol{\theta}^{k+1} = \boldsymbol{\theta}^{0} + \sqrt{\hat{\mathbf{L}}} \mathbf{x}^{k+1}.
\end{gather*}
Then, subtracting $\boldsymbol{\theta}^{k}$ from $\boldsymbol{\theta}^{k+1}$ yields
\begin{gather*}
    \boldsymbol{\theta}^{k+1} = \boldsymbol{\theta}^{k} - \alpha \hat{\mathbf{L}} \nabla F(\boldsymbol{\theta}^{0} + \sqrt{\hat{\mathbf{L}}}\mathbf{x}^{k}) = \boldsymbol{\theta}^{k} - \alpha \hat{\mathbf{L}} \cdot \nabla  F(\boldsymbol{\theta}^{k}).
\end{gather*}
Therefore, the sequence $\{\boldsymbol{\theta}^{k}\}$ generated by \eqref{eq: LGD aggregate form} follows the same sequence as gradient descent applied to $\Psi_{\boldsymbol{\theta}^{0}}$ from the same initial point $\boldsymbol{\theta}^{0} \in (\mathbb{R}^{n})^{m}$ and $\mathbf{x}^{0} = \bm{0} \in (\mathbb{R}^{n})^{m}$ with the same fixed step-size $\alpha > 0$ as claimed.

\label{lem: Sufficient descent}
    Let Assumptions \ref{ass: Lipschitz}, \ref{ass: Coercivity} and \ref{ass: Network} hold. Given initial point $\boldsymbol{\theta}^{0} \in (\mathbb{R}^{n})^{m}$, for any fixed step-size $0 < \alpha < 2/L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}$ with initial iterate $\mathbf{x}^{0} = \bm{0} \in (\mathbb{R}^{n})^{m}$, the sequence $\{\mathbf{x}^{k}\}$ generated by \eqref{eq: LGD with auxiliary function} satisfies that
    \begin{gather*}
        \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k+1}) - \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k}) \le (-\frac{1}{\alpha} + \frac{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}}{2}) \norm{\mathbf{x}^{k+1} - \mathbf{x}^{k}}^{2} \le 0.
    \end{gather*}

By Assumption \ref{ass: Lipschitz}, in view of the update in \eqref{eq: LGD with auxiliary function},  applying Taylor’s theorem yields
\begin{align}
\label{eq: Descent lemma}
    \begin{aligned}
        \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k+1}) - \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k}) & \le \nabla \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k})^{\top} (\mathbf{x}^{k+1} - \mathbf{x}^{k}) + \frac{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}}{2} \norm{\mathbf{x}^{k+1} - \mathbf{x}^{k}}^{2}\\
        & \le (-\frac{1}{\alpha} + \frac{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}}{2}) \norm{\mathbf{x}^{k+1} - \mathbf{x}^{k}}^{2}.
    \end{aligned}
\end{align}
Thus, for any fixed $0 < \alpha < 2/L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}$,
\begin{gather*}
    \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k+1}) - \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k}) \le 0
\end{gather*}
as claimed.

Given
\[
    \boldsymbol{\theta}
    =
    \boldsymbol{\theta}^{0}
    +
    \sqrt{\hat{\mathbf{L}}}\mathbf{x},
\]
from condition i), it follows that
\begin{gather*}
    \norm{
    \sqrt{\hat{\mathbf{L}}}
    \nabla F(\boldsymbol{\theta})
    }
    =
    \norm{
    \nabla
    \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x})
    }
    \le \epsilon.
\end{gather*}
Moreover, since the initial point
$\boldsymbol{\theta}^{0}$ is feasible and
\[
    (\bm{1}_{m}^{\top}\otimes\mathbf{I}_{n})
    \sqrt{\hat{\mathbf{L}}}
    =
    \bm{0}^{\top},
\]
it follows that
\begin{gather*}
    (\bm{1}_{m}^{\top}\otimes\mathbf{I}_{n})
    \boldsymbol{\theta}
    =
    (\bm{1}_{m}^{\top}\otimes\mathbf{I}_{n})
    \left(
    \boldsymbol{\theta}^{0}
    +
    \sqrt{\hat{\mathbf{L}}}\mathbf{x}
    \right) =
    (\bm{1}_{m}^{\top}\otimes\mathbf{I}_{n})
    \boldsymbol{\theta}^{0}
    =
    \bm{r}.
\end{gather*}
From condition ii), it follows that for all
$\mathbf{e}\in(\mathbb{R}^{n})^{m}$,
\begin{gather*}
    \mathbf{e}^{\top}
    \sqrt{\hat{\mathbf{L}}}
    \nabla^{2}F(\boldsymbol{\theta})
    \sqrt{\hat{\mathbf{L}}}
    \mathbf{e}
    =
    \mathbf{e}^{\top}
    \nabla^{2}
    \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x})
    \mathbf{e}
    \ge
    -\gamma\norm{\mathbf{e}}^{2}.
\end{gather*}
By Assumption~\ref{ass: Network},
\[
    \operatorname{range}
    \left(\sqrt{\hat{\mathbf{L}}}\right)
    =
    \mathcal{T}
    =
    \left\{
    \mathbf{d}\in(\mathbb{R}^{n})^{m}
    :
    (\bm{1}_{m}^{\top}\otimes\mathbf{I}_{n})
    \mathbf{d}
    =
    \bm{0}
    \right\}.
\]
Hence, for every $\mathbf{d}\in\mathcal{T}$, we can choose
$\mathbf{e}\in\mathcal{T}$ such that
\[
    \mathbf{d}
    =
    \sqrt{\hat{\mathbf{L}}}\mathbf{e}.
\]
Since $\mathbf{e}\in\mathcal{T}$ and the smallest positive
eigenvalue of $\hat{\mathbf{L}}$ is
$\lambda_{\min}^{+}(\mathbf{L})$, we have
\begin{gather*}
    \norm{\mathbf{d}}^{2}
    =
    \mathbf{e}^{\top}
    \hat{\mathbf{L}}
    \mathbf{e}
    \ge
    \lambda_{\min}^{+}(\mathbf{L})
    \norm{\mathbf{e}}^{2}.
\end{gather*}
Therefore,
\begin{gather*}
    \mathbf{d}^{\top}
    \nabla^{2}F(\boldsymbol{\theta})
    \mathbf{d}
    \ge
    -\gamma\norm{\mathbf{e}}^{2} \ge
    -
    \frac{\gamma}
    {\lambda_{\min}^{+}(\mathbf{L})}
    \norm{\mathbf{d}}^{2},
\end{gather*}
as claimed.

For the sake of clarity in the forthcoming proofs, we define the following key parameters: given $\rho \ge 1$ (to be specified later), let 
\begin{gather}
    \label{eq: parameters}
    \alpha\coloneqq\frac{1}{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}\rho^{7}},
    \qquad
    d\coloneqq\frac{\epsilon_H}{20L_{\Psi_{\boldsymbol{\theta}^{0}}}^{H}\rho^{2}},
    \qquad
    r\coloneqq\left\lceil\frac{\rho}{\alpha\epsilon_H}\right\rceil .
\end{gather}

\label{pro: Boole-frechet Inequality}
    For events $\mathcal{E}_1,\ldots,\mathcal{E}_n$,
    \begin{gather*}
        \max_{1\leq i\leq n}\mathbb{P}(\mathcal{E}_i)\leq\mathbb{P}\left(\bigcup_{i=1}^{n}\mathcal{E}_i\right)\leq\sum_{i=1}^{n}\mathbb{P}(\mathcal{E}_i),
    \end{gather*}
    and consequently
    \begin{gather}
    \label{eq: Boole's inequality}
        \mathbb{P}\left[\bigcap_{i=1}^{n}\mathcal{E}_i\right]\geq1-\sum_{i=1}^{n}\mathbb{P}[\bar{\mathcal{E}}_i]=1-\sum_{i=1}^{n}\left(1-\mathbb{P}[\mathcal{E}_i]\right),
    \end{gather}
    where $\bar{\mathcal{E}}_i$ denotes the complement of $\mathcal{E}_i$.

Specifically, given events of the form $\mathcal{E}_{i} := \{\omega \in \Omega : P_{i}\} \subseteq \Omega$ and $\mathcal{E}_{j} := \{\omega \in \Omega : P_{j}\} \subseteq \Omega$, where $P_{i}$ and $P_{j}$ are logical predicates defined on $\omega$, we denote:
\begin{gather}
\label{eq: Material implication}
    \mathcal{E}_{i} \Rightarrow \mathcal{E}_{j} := \left\{ \omega \in \Omega :~P_{i} \Rightarrow P_{j} \right\} = \left\{ \omega \in \Omega :~\neg P_{i} \lor P_{j} \right\} = \bar{\mathcal{E}}_{i} \cup \mathcal{E}_{j}.
\end{gather}

\label{lem: Decrease}
    Let Assumptions \ref{ass: Lipschitz} and \ref{ass: Random perturbation} hold. Given $\rho\geq1$, let $\alpha$ and $d$ be defined in \eqref{eq: parameters}. Then, for any $\mathbf{x}^{0}\in(\mathbb{R}^{n})^{m}$ and $t_{0},t\geq0$,
    \begin{multline}
    \label{eq: Decomposition of the change}
    \mathbb{P}\Bigg[\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{t_{0}+t})-\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{t_{0}})\leq-\frac{\alpha}{2}\sum_{k=0}^{t-1}\|\nabla\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{t_{0}+k})\|^{2}\\
    +mn\alpha\sigma^{2}(t+\sqrt{t\rho}+\rho)\Bigg]\geq1-2\mathrm{e}^{-\rho},
    \end{multline}
    where $\{\mathbf{x}^{k}\}$ is generated by \eqref{eq: NLGD with auxiliary function 1}.

Since the dynamics in \eqref{eq: NLGD with auxiliary function 1} are time-invariant, it suffices to consider $t_{0}=0$. By Assumption \ref{ass: Lipschitz} and Taylor's theorem, for any $t\geq0$,
\begin{align*}
    \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{t+1})-\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{t})
    &\leq \nabla\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{t})^{\top}(\mathbf{x}^{t+1}-\mathbf{x}^{t})+\frac{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}}{2}\|\mathbf{x}^{t+1}-\mathbf{x}^{t}\|^{2}\\
    &=\left(-\alpha+\frac{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}\alpha^{2}}{2}\right)\|\nabla\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{t})\|^{2}+\frac{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}\alpha^{2}}{2}\|\mathbf{n}^{t}\|^{2}\\
    &\quad+\left(-\alpha+L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}\alpha^{2}\right)\nabla\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{t})^{\top}\mathbf{n}^{t}.
\end{align*}
Since $\rho\geq1$ implies $\alpha=1/(L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}\rho^{7})\leq1/L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}$, Cauchy--Schwarz and Young's inequalities give
\begin{gather*}
    \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{t+1})-\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{t})\leq-\frac{\alpha}{2}\|\nabla\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{t})\|^{2}+\frac{\alpha}{2}\|\mathbf{n}^{t}\|^{2}.
\end{gather*}
Summing over $t$ yields
\begin{gather}
\label{eq: descent}
    \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{t})-\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{0})\leq-\frac{\alpha}{2}\sum_{k=0}^{t-1}\left(\|\nabla\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k})\|^{2}-\|\mathbf{n}^{k}\|^{2}\right).
\end{gather}
Since $\sum_{k=0}^{t-1}\|\mathbf{n}^{k}/\sigma\|^{2}$ is chi-square distributed with $tmn$ degrees of freedom, Lemma 1 in \cite{laurent2000adaptive} gives
\begin{gather}
\label{eq: descent third term}
    \mathbb{P}\left[\sum_{k=0}^{t-1}\|\mathbf{n}^{k}\|^{2}\leq2mn\sigma^{2}(t+\sqrt{t\rho}+\rho)\right]\geq1-2\mathrm{e}^{-\rho}.
\end{gather}
Combining \eqref{eq: descent} and \eqref{eq: descent third term} proves \eqref{eq: Decomposition of the change}.

\label{lem: Improve or Localize}
Let Assumptions \ref{ass: Lipschitz} and \ref{ass: Random perturbation} hold. Given $\rho\geq1$, let $\alpha$ and $d$ be defined in \eqref{eq: parameters}. Then, for any $\mathbf{x}^{0}\in(\mathbb{R}^{n})^{m}$ and $t_{0},t\geq0$,
\begin{multline*}
    \mathbb{P}\Big[\forall\tau\in(0,t],~\|\mathbf{x}^{t_{0}+\tau}-\mathbf{x}^{t_{0}}\|^{2}
    \leq4\alpha\tau\big(\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{t_{0}})-\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{t_{0}+\tau})\big)\\
    +8mn\alpha^{2}\sigma^{2}\tau(\tau+\sqrt{\tau\rho}+\rho)\Big]\geq1-4t\mathrm{e}^{-\rho},
\end{multline*}
where $\{\mathbf{x}^{k}\}$ is generated by \eqref{eq: NLGD with auxiliary function 1}.

By time invariance, it suffices to consider $t_{0}=0$. Define
\begin{gather*}
    \mathcal{E}_{a,\tau}:=\left\{\sum_{k=0}^{\tau-1}\|\nabla\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k})\|^{2}
    \leq2\alpha^{-1}\big(\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{0})-\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{\tau})\big)
    +2mn\sigma^{2}(\tau+\sqrt{\tau\rho}+\rho)\right\},
\end{gather*}
and
\begin{gather*}
    \mathcal{E}_{b,\tau}:=\left\{\sum_{k=0}^{\tau-1}\|\mathbf{n}^{k}\|^{2}
    \leq2mn\sigma^{2}(\tau+\sqrt{\tau\rho}+\rho)\right\}.
\end{gather*}
By Lemma \ref{lem: Decrease},
\begin{gather}
    \label{eq: localize first term}
    \mathbb{P}[\mathcal{E}_{a,\tau}]\geq1-2\mathrm{e}^{-\rho}.
\end{gather}
Moreover, by Cauchy--Schwarz,
\begin{align}
    \label{eq: localize}
    \|\mathbf{x}^{\tau}-\mathbf{x}^{0}\|^{2}
    &=\alpha^{2}\left\|\sum_{k=0}^{\tau-1}\left(\nabla\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k})+\mathbf{n}^{k}\right)\right\|^{2}\nonumber\\
    &\leq2\alpha^{2}\tau\left(\sum_{k=0}^{\tau-1}\|\nabla\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k})\|^{2}
    +\sum_{k=0}^{\tau-1}\|\mathbf{n}^{k}\|^{2}\right).
\end{align}
Hence, on $\mathcal{E}_{a,\tau}\cap\mathcal{E}_{b,\tau}$,
\begin{gather*}
    \|\mathbf{x}^{\tau}-\mathbf{x}^{0}\|^{2}
    \leq4\alpha\tau\big(\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{0})-\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{\tau})\big) +8mn\alpha^{2}\sigma^{2}\tau(\tau+\sqrt{\tau\rho}+\rho).
\end{gather*}
Therefore, by \eqref{eq: Boole's inequality}, \eqref{eq: descent third term}, and \eqref{eq: localize first term},
\begin{align*}
    \mathbb{P}\left[\bigcap_{\tau=1}^{t}\left(\mathcal{E}_{a,\tau}\cap\mathcal{E}_{b,\tau}\right)\right]
    &\geq1-\sum_{\tau=1}^{t}\big(1-\mathbb{P}[\mathcal{E}_{a,\tau}]\big)
    -\sum_{\tau=1}^{t}\big(1-\mathbb{P}[\mathcal{E}_{b,\tau}]\big)\\
    &\geq1-4t\mathrm{e}^{-\rho},
\end{align*}
which proves the result.

\label{lem: Localization}
Let Assumptions \ref{ass: Lipschitz} and \ref{ass: Random perturbation} hold. Given $\rho\geq1$, let $\alpha$, $d$, and $r$ be defined in \eqref{eq: parameters}. If $\{\mathbf{y}^{k}\}$ and $\{\mathbf{z}^{k}\}$ are coupling sequences, then
\begin{gather}
    \label{eq: Localization}
    \mathbb{P}\Big[\mathcal{E}_{A}^{0,r}\cup\mathcal{E}_{B}^{0,r}\Big]\geq1-8r\mathrm{e}^{-\rho}.
\end{gather}

Applying Lemma \ref{lem: Improve or Localize} to the coupling sequences gives, for any $t>0$,
    \begin{multline}
        \label{eq: Localize y}
        \mathbb{P}\Big[\forall\tau\in(0,t],~\|\mathbf{y}^{\tau}-\mathbf{y}^{0}\|^{2}
        \leq4\alpha\tau\big(\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{y}^{0})-\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{y}^{\tau})\big)\\
        +8mn\alpha^{2}\sigma^{2}\tau(\tau+\sqrt{\tau\rho}+\rho)\Big]\geq1-4t\mathrm{e}^{-\rho},
    \end{multline}
    and similarly
    \begin{multline}
        \label{eq: Localize z}
        \mathbb{P}\Big[\forall\tau\in(0,t],~\|\mathbf{z}^{\tau}-\mathbf{z}^{0}\|^{2}
        \leq4\alpha\tau\big(\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{z}^{0})-\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{z}^{\tau})\big)\\
        +8mn\alpha^{2}\sigma^{2}\tau(\tau+\sqrt{\tau\rho}+\rho)\Big]\geq1-4t\mathrm{e}^{-\rho}.
    \end{multline}
    By \eqref{eq: Boole's inequality},
    \begin{multline}
        \label{eq: coupling sequences 1}
        \mathbb{P}\Big[\forall\tau\in(0,t],~
        \max\{\|\mathbf{y}^{\tau}-\mathbf{y}^{0}\|^{2},\|\mathbf{z}^{\tau}-\mathbf{z}^{0}\|^{2}\}\leq4\alpha\tau\\
        \Big(\max\{\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{y}^{0})-\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{y}^{\tau}),
        \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{z}^{0})-\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{z}^{\tau})\}
        +2mn\alpha\sigma^{2}(\tau+\sqrt{\tau\rho}+\rho)\Big)\Big]\geq1-8t\mathrm{e}^{-\rho}.
    \end{multline}
    Define
    \begin{multline}
        \label{eq: D1}
        \mathcal{C}^{r}\coloneqq\Big\{\forall\tau\in(0,r],~
        \max\{\|\mathbf{y}^{\tau}-\mathbf{y}^{0}\|^{2},\|\mathbf{z}^{\tau}-\mathbf{z}^{0}\|^{2}\}\\
        \leq4\alpha\tau\Big(\max\{\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{y}^{0})-\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{y}^{\tau}),
        \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{z}^{0})-\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{z}^{\tau})\}
        +2mn\alpha\sigma^{2}(\tau+\sqrt{\tau\rho}+\rho)\Big)\Big\}.
    \end{multline}
    By \eqref{eq: coupling sequences 1}, $\mathbb{P}[\mathcal{C}^{r}]\geq1-8r\mathrm{e}^{-\rho}$. On $\mathcal{C}^{r}\cap\bar{\mathcal{E}}_{A}^{0,r}$, Definition \eqref{eq: Event A} gives, for every $\tau\in(0,r]$,
    \begin{gather*}
        \max\{\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{y}^{0})-\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{y}^{\tau}),
        \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{z}^{0})-\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{z}^{\tau})\}<\ell_{s}.
    \end{gather*}
    Hence, using $\tau\leq r$ and \eqref{eq: ls},
    \begin{align*}
        \max\{\|\mathbf{y}^{\tau}-\mathbf{y}^{0}\|^{2},\|\mathbf{z}^{\tau}-\mathbf{z}^{0}\|^{2}\}
        &\leq4\alpha\tau\Big(\ell_{s}+2mn\alpha\sigma^{2}(\tau+\sqrt{\tau\rho}+\rho)\Big)\\
        &\leq4\alpha r\Big(\ell_{s}+2mn\alpha\sigma^{2}(r+\sqrt{r\rho}+\rho)\Big)=d^{2}.
    \end{align*}
    Thus, $\mathcal{C}^{r}\cap\bar{\mathcal{E}}_{A}^{0,r}\subseteq\mathcal{E}_{B}^{0,r}$. By \eqref{eq: Material implication}, this implies $\mathcal{C}^{r}\subseteq\mathcal{E}_{A}^{0,r}\cup\mathcal{E}_{B}^{0,r}$. Therefore,
    \begin{gather*}
        \mathbb{P}\Big[\mathcal{E}_{A}^{0,r}\cup\mathcal{E}_{B}^{0,r}\Big]\geq\mathbb{P}[\mathcal{C}^{r}]\geq1-8r\mathrm{e}^{-\rho},
    \end{gather*}
    which proves the result.

\label{lem: Dynamic}
Let Assumption \ref{ass: Random perturbation} hold and let $\alpha$ be defined in \eqref{eq: parameters}. If $\{\mathbf{y}^{k}\}$ and $\{\mathbf{z}^{k}\}$ are coupling sequences, then for any $k\geq0$,
\begin{gather*}
    \Delta^{k}=\Delta_{1}^{k}+\Delta_{2}^{k},
\end{gather*}
where $\Delta_{1}^{k}$ and $\Delta_{2}^{k}$ are defined in \eqref{eq: Dynamic expression}.

From \eqref{eq: NLGD with auxiliary function 1},
\begin{align*}
    \Delta^{k+1}
    &=\Delta^{k}-\alpha\left(\nabla\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{y}^{k})-\nabla\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{z}^{k})+\delta_{\mathbf{n}}^{k}\right)\\
    &=\Delta^{k}-\alpha\left(\mathcal{I}^{k}\Delta^{k}+\delta_{\mathbf{n}}^{k}\right)\\
    &=(\mathbf{I}_{mn}-\alpha\mathcal{H}^{0})\Delta^{k}-\alpha\left((\mathcal{I}^{k}-\mathcal{H}^{0})\Delta^{k}+\delta_{\mathbf{n}}^{k}\right).
\end{align*}
Hence, for $0\leq\tau\leq k-1$, multiplying by $(\mathbf{I}_{mn}-\alpha\mathcal{H}^{0})^{k-\tau-1}$ gives
\begin{multline}
    \label{eq: Delat t}
    (\mathbf{I}_{mn}-\alpha\mathcal{H}^{0})^{k-\tau-1}\Delta^{\tau+1}
    =(\mathbf{I}_{mn}-\alpha\mathcal{H}^{0})^{k-\tau}\Delta^{\tau}\\
    -\alpha(\mathbf{I}_{mn}-\alpha\mathcal{H}^{0})^{k-\tau-1}
    \left((\mathcal{I}^{\tau}-\mathcal{H}^{0})\Delta^{\tau}+\delta_{\mathbf{n}}^{\tau}\right).
\end{multline}
Summing \eqref{eq: Delat t} over $\tau=0,\ldots,k-1$ and using $\Delta^{0}=0$ yields
\begin{gather*}
    \Delta^{k}=-\alpha\sum_{\tau=0}^{k-1}(\mathbf{I}_{mn}-\alpha\mathcal{H}^{0})^{k-\tau-1}
    \left((\mathcal{I}^{\tau}-\mathcal{H}^{0})\Delta^{\tau}+\delta_{\mathbf{n}}^{\tau}\right)
    =\Delta_{1}^{k}+\Delta_{2}^{k},
\end{gather*}
as claimed.

\label{lem: Dynamic concentration 1}
Let Assumption \ref{ass: Random perturbation} hold and $\epsilon_{H}>0$. There exists $\rho_{\min,1}\geq1$ such that for any $\rho\geq\rho_{\min,1}$, with $\alpha$ and $r$ defined in \eqref{eq: parameters}, the following holds: if $\lambda_{\min}(\nabla^{2}\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{0}))<-\epsilon_{H}$ and $\{\mathbf{y}^{k}\}$ and $\{\mathbf{z}^{k}\}$ are coupling sequences, then for any $k\geq0$,
\begin{gather*}
    \mathbb{P}\left[\|\Delta_{2}^{k}\|\leq\alpha\varsigma^{0}(k)\sqrt{2\rho}\right]\geq1-2\mathrm{e}^{-\rho},\\
    \mathbb{P}\left[\|\Delta_{2}^{r}\|\geq\frac{\alpha\varsigma^{0}(r)}{5}\right]\geq\frac{2}{3},
\end{gather*}
where $\varsigma^{0}(k)$ is defined in \eqref{eq: varsigma}.

By Definition \ref{def: Coupling sequence}, $\delta_{\mathbf{n}}^{k}$ lies in $\mathrm{span}(\mathbf{e}_{\alpha})$. Taking $\mathbf{e}_{\alpha}$ to have unit norm, define
\begin{gather}
    \label{eq: Sum of dev}
    S_{k}\coloneqq\mathbf{e}_{\alpha}^{\top}\sum_{\tau=0}^{k-1}\left(\mathbf{I}_{mn}-\alpha\nabla^{2}\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{0})\right)^{k-1-\tau}\delta_{\mathbf{n}}^{\tau}.
\end{gather}
Since $\nabla^{2}\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{0})\mathbf{e}_{\alpha}=-\gamma^{0}\mathbf{e}_{\alpha}$ and the perturbations are Gaussian, $S_{k}$ is Gaussian with zero mean and variance
\begin{gather*}
    (\Sigma_{k})^{2}=4\frac{(1+\alpha\gamma^{0})^{2k}-1}{2\alpha\gamma^{0}+(\alpha\gamma^{0})^{2}}\sigma^{2}\leq(\varsigma^{0}(k))^{2}.
\end{gather*}
Moreover, $\Delta_{2}^{k}=-\alpha S_{k}\mathbf{e}_{\alpha}$, so $\|\Delta_{2}^{k}\|=\alpha|S_{k}|$. The first inequality therefore follows from the Gaussian concentration bound.

Since $\alpha,\gamma^{0}>0$, there exists $\rho_{\min,1}\geq1$ such that for all $\rho\geq\rho_{\min,1}$,
\begin{gather*}
    (1+\alpha\gamma^{0})^{2r}-1\geq\frac{1}{3}(1+\alpha\gamma^{0})^{2r},
\end{gather*}
and hence $\Sigma_{r}\geq\varsigma^{0}(r)/\sqrt{3}$. Letting $\rho^{\prime}=\sqrt{3}/5$ and using $S_{r}/\Sigma_{r}\sim\mathcal{N}(0,1)$,
\begin{align*}
    \mathbb{P}\left[\|\Delta_{2}^{r}\|\geq\frac{\alpha\varsigma^{0}(r)}{5}\right]
    &\geq\mathbb{P}\left[|S_{r}|\geq\Sigma_{r}\rho^{\prime}\right]\\
    &\geq1-\frac{2\rho^{\prime}}{\sqrt{2\pi}}
    \geq\frac{2}{3},
\end{align*}
which proves the result.

\label{lem: Dynamic concentration 2}
Let Assumptions \ref{ass: Lipschitz} and \ref{ass: Random perturbation} hold and $\epsilon_H>0$. There exists $\rho_{\min,3}\newline\geq1$ such that, for any $\rho\geq\rho_{\min,3}$, with $\alpha$, $d$, and $r$ defined in \eqref{eq: parameters}, the following holds. If $\lambda_{\min}(\nabla^{2}\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{0}))<-\epsilon_H$ and $\{\mathbf{y}^{k}\}$ and $\{\mathbf{z}^{k}\}$ are coupling sequences, then
\begin{gather*}
    \mathbb{P}\Big[\mathcal{E}_{A}^{0,r}\cup\mathcal{E}_{C}^{0,r}\Big]\geq1-(2r^{2}+8r)\mathrm{e}^{-\rho}.
\end{gather*}

Lemma \ref{lem: Dynamic concentration 1} and the union bound give, for any $t\geq0$,
\begin{gather}
    \label{eq: Delta 2 for t times}
    \mathbb{P}\left[\forall\tau\in(0,t],~\|\Delta_{2}^{\tau}\|\leq\alpha\varsigma^{0}(\tau)\sqrt{2\rho}\right]\geq1-2t\mathrm{e}^{-\rho}.
\end{gather}
Define the stronger event
\begin{gather*}
    \mathcal{D}^{t}\coloneqq\left\{\forall\tau\in(0,t],~\|\Delta_{1}^{\tau}\|\leq\frac{\alpha\varsigma^{0}(\tau)}{10}\right\}.
\end{gather*}
Since $\varsigma^{0}(\tau)$ is nondecreasing, $\mathcal{D}^{t}\subseteq\mathcal{E}_{C}^{0,t}$. We prove by induction that, for $t\leq r$,
\begin{gather}
    \label{eq: B to C}
    \mathbb{P}\Big[\mathcal{E}_{B}^{0,t}\Rightarrow\mathcal{D}^{t}\Big]\geq1-2t^{2}\mathrm{e}^{-\rho}.
\end{gather}
The claim is immediate for $t=0$ since $\Delta_{1}^{0}=\Delta_{2}^{0}=\Delta^{0}=\bm{0}$. Suppose it holds for $t$, and define
\begin{gather}
    \label{eq: B to C and}
    \mathcal{G}^{t}\coloneqq\left\{\forall\tau\in(0,t],~\|\Delta_{2}^{\tau}\|\leq\alpha\varsigma^{0}(\tau)\sqrt{2\rho}\right\}.
\end{gather}
On $\mathcal{D}^{t}\cap\mathcal{G}^{t}$, Lemma \ref{lem: Dynamic} yields
\begin{gather*}
    \|\Delta^{\tau}\|\leq\alpha\varsigma^{0}(\tau)\left(\sqrt{2\rho}+\frac{1}{10}\right),\qquad \tau\in(0,t].
\end{gather*}
Hence, by \eqref{eq: B to C}, \eqref{eq: Delta 2 for t times}, and the union bound,
\begin{multline}
    \label{eq: Set B to C and Delta}
    \mathbb{P}\Big[\mathcal{E}_{B}^{0,t}\Rightarrow\big(\mathcal{D}^{t}\cap
    \{\forall\tau\in(0,t]:~\|\Delta^{\tau}\|\leq\alpha\varsigma^{0}(\tau)(\sqrt{2\rho}+\tfrac{1}{10})\}\big)\Big]\\
    \geq1-2(t^{2}+t)\mathrm{e}^{-\rho}.
\end{multline}
By Hessian Lipschitz continuity, $\|\mathcal{I}^{\tau}-\mathcal{H}^{0}\|\leq L_{\Psi_{\boldsymbol{\theta}^{0}}}^{H}\max\{\|\mathbf{y}^{\tau}-\mathbf{y}^{0}\|,\|\mathbf{z}^{\tau}-\mathbf{z}^{0}\|\}$. Moreover, $\alpha L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}\leq1$ implies $\|\mathbf{I}_{mn}-\alpha\mathcal{H}^{0}\|\leq1+\alpha\gamma^{0}$. Hence, by \eqref{eq: Dynamic expression},
\begin{gather}
    \label{eq: Delta 1}
    \|\Delta_{1}^{t+1}\|\leq\alpha\sum_{\tau=0}^{t}(1+\alpha\gamma^{0})^{t-\tau}L_{\Psi_{\boldsymbol{\theta}^{0}}}^{H}
    \max\{\|\mathbf{y}^{\tau}-\mathbf{y}^{0}\|,\|\mathbf{z}^{\tau}-\mathbf{z}^{0}\|\}\|\Delta^{\tau}\|.
\end{gather}
Moreover,
\begin{gather}
    \label{eq: B to B at t+1}
    \mathcal{E}_{B}^{0,t+1}\subseteq\mathcal{E}_{B}^{0,t}.
\end{gather}
Since $\Delta^{0}=\bm{0}$ and $\varsigma^{0}(\tau)$ is proportional to $(1+\alpha\gamma^{0})^{\tau}$,
\begin{gather}
    \label{eq: Geometric sequence}
    \sum_{\tau=1}^{t}(1+\alpha\gamma^{0})^{t-\tau}\varsigma^{0}(\tau)=t\varsigma^{0}(t).
\end{gather}
Therefore, on the event in \eqref{eq: Set B to C and Delta} and $\mathcal{E}_{B}^{0,t+1}$,
\begin{gather*}
    \|\Delta_{1}^{t+1}\|\leq\alpha^{2}L_{\Psi_{\boldsymbol{\theta}^{0}}}^{H}dt\varsigma^{0}(t)\left(\sqrt{2\rho}+\frac{1}{10}\right).
\end{gather*}
Since $r=\lceil\rho/(\alpha\epsilon_H)\rceil\leq2\rho/(\alpha\epsilon_H)$ for sufficiently large $\rho$,
\[
    L_{\Psi_{\boldsymbol{\theta}^{0}}}^{H}\alpha r d(10\sqrt{2\rho}+1)
    \leq\frac{10\sqrt{2\rho}+1}{10\rho}.
\]
Hence there exists $\rho_{\min,2}\geq1$ such that, for all $\rho\geq\rho_{\min,2}$,
\begin{gather*}
    d\leq\frac{1}{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{H}\alpha r(10\sqrt{2\rho}+1)}.
\end{gather*}
Using $t\leq r-1$ and $\varsigma^{0}(t)\leq\varsigma^{0}(t+1)$ therefore gives
\begin{gather}
    \label{eq: B to C at t+1}
    \mathbb{P}\Big[\mathcal{E}_{B}^{0,t+1}\Rightarrow\mathcal{D}^{t+1}\Big]
    \geq1-2(t^{2}+t)\mathrm{e}^{-\rho}
    \geq1-2(t+1)^{2}\mathrm{e}^{-\rho}.
\end{gather}
Thus, \eqref{eq: B to C} holds for all $t\leq r$. Since $\mathcal{D}^{r}\subseteq\mathcal{E}_{C}^{0,r}$,
\begin{gather*}
    \mathbb{P}\Big[\mathcal{E}_{B}^{0,r}\Rightarrow\mathcal{E}_{C}^{0,r}\Big]\geq1-2r^{2}\mathrm{e}^{-\rho}.
\end{gather*}
By Lemma \ref{lem: Localization},
\begin{gather*}
    \mathbb{P}\Big[\bar{\mathcal{E}}_{A}^{0,r}\Rightarrow\mathcal{E}_{B}^{0,r}\Big]
    =\mathbb{P}\Big[\mathcal{E}_{A}^{0,r}\cup\mathcal{E}_{B}^{0,r}\Big]
    \geq1-8r\mathrm{e}^{-\rho}.
\end{gather*}
Since $(\bar{\mathcal{E}}_{A}^{0,r}\Rightarrow\mathcal{E}_{B}^{0,r})\cap(\mathcal{E}_{B}^{0,r}\Rightarrow\mathcal{E}_{C}^{0,r})\subseteq(\bar{\mathcal{E}}_{A}^{0,r}\Rightarrow\mathcal{E}_{C}^{0,r})$, \eqref{eq: Material implication} and the union bound yield
\begin{gather*}
    \mathbb{P}\Big[\mathcal{E}_{A}^{0,r}\cup\mathcal{E}_{C}^{0,r}\Big]
    \geq1-(2r^{2}+8r)\mathrm{e}^{-\rho}.
\end{gather*}
Taking $\rho_{\min,3}\geq\max\{\rho_{\min,1},\rho_{\min,2}\}$ proves the result.

\begin{multline}
        \label{eq: Set B to C and Delta}
        \mathbb{P}\Big[\mathcal{E}_{B}^{0,t}\Rightarrow\big(\mathcal{D}^{t}\cap
        \{\forall\tau\in(0,t]:~\|\Delta^{\tau}\|\leq\alpha\varsigma^{0}(\tau)(\sqrt{2\rho}+\tfrac{1}{10})\}\big)\Big]\\
        \geq1-2(t^{2}+t)\mathrm{e}^{-\rho}.
    \end{multline}

Let $\{\mathbf{y}^{k}\}$ and $\{\mathbf{z}^{k}\}$ be the reflection coupling from Definition \ref{def: Coupling sequence}. By Lemmas \ref{lem: Dynamic concentration 1} and \ref{lem: Dynamic concentration 2}, for sufficiently large $\rho$,
\begin{gather}
    \label{eq: Delta two}
    \mathbb{P}\Big[\|\Delta_{2}^{r}\|\geq\frac{\alpha\varsigma^{0}(r)}{5}\Big]\geq\frac{2}{3},
\end{gather}
and
\begin{gather}
    \label{eq: Delta one}
    \mathbb{P}\Big[\mathcal{E}_{A}^{0,r}\cup\mathcal{E}_{C}^{0,r}\Big]
    \geq1-(2r^{2}+8r)\mathrm{e}^{-\rho}.
\end{gather}
Since $\gamma^{0}>\epsilon_H$ and $r=\lceil\rho/(\alpha\epsilon_H)\rceil$, we have $\alpha\gamma^{0}r\geq\rho$. Moreover, gradient Lipschitz continuity gives $\gamma^{0}\leq L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}$, so $\alpha\gamma^{0}\leq\rho^{-7}\leq1$. Using $\log(1+u)\geq u/2$ for $u\in[0,1]$,
\begin{gather*}
    (1+\alpha\gamma^{0})^{r}
    \geq\exp\!\left(\frac{\alpha\gamma^{0}r}{2}\right)
    \geq\mathrm{e}^{\rho/2}.
\end{gather*}
Hence, by \eqref{eq: varsigma},
\begin{gather*}
    \frac{\alpha\varsigma^{0}(r)}{20}
    \geq
    \frac{\sigma\sqrt{\alpha}}{10\sqrt{3L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}}}\mathrm{e}^{\rho/2}.
\end{gather*}
With $d=\epsilon_H/(20L_{\Psi_{\boldsymbol{\theta}^{0}}}^{H}\rho^{2})$ and $\sigma^{2}$ as in \eqref{eq: Variance}, there exists $\rho_{\min,4}\geq1$ such that for all $\rho\geq\rho_{\min,4}$,
\begin{gather}
    \label{eq: varsigma lower bound}
    \frac{\alpha\varsigma^{0}(r)}{20}\geq d.
\end{gather}
Therefore, on $\mathcal{E}_{C}^{0,r}\cap\{\|\Delta_{2}^{r}\|\geq\alpha\varsigma^{0}(r)/5\}$,
\begin{gather*}
    \max\{\|\mathbf{y}^{r}-\mathbf{y}^{0}\|,\|\mathbf{z}^{r}-\mathbf{z}^{0}\|\}
    \geq\frac12\|\Delta^{r}\|
    \geq\frac12\big(\|\Delta_{2}^{r}\|-\|\Delta_{1}^{r}\|\big)
    \geq\frac{\alpha\varsigma^{0}(r)}{20}
    \geq d,
\end{gather*}
and hence
\begin{gather}
    \label{eq: Delta 2 and C to B}
    \left\{\|\Delta_{2}^{r}\|\geq\frac{\alpha\varsigma^{0}(r)}{5}\right\}
    \cap\mathcal{E}_{C}^{0,r}
    \subseteq\bar{\mathcal{E}}_{B}^{0,r}.
\end{gather}

Let
\[
    \mathcal{G}_{1}\coloneqq\left\{\|\Delta_{2}^{r}\|\geq\frac{\alpha\varsigma^{0}(r)}{5}\right\},\quad
    \mathcal{G}_{2}\coloneqq\mathcal{E}_{A}^{0,r}\cup\mathcal{E}_{C}^{0,r},\quad
    \mathcal{G}_{3}\coloneqq\mathcal{E}_{A}^{0,r}\cup\mathcal{E}_{B}^{0,r}.
\]
By \eqref{eq: Delta 2 and C to B}, $\mathcal{G}_{1}\cap\mathcal{G}_{2}\cap\mathcal{G}_{3}\subseteq\mathcal{E}_{A}^{0,r}$. Thus, by \eqref{eq: Delta two}, \eqref{eq: Delta one}, Lemma \ref{lem: Localization}, and the union bound,
\begin{gather*}
    \mathbb{P}[\mathcal{E}_{A}^{0,r}]
    \geq\frac{2}{3}-(2r^{2}+16r)\mathrm{e}^{-\rho}.
\end{gather*}
Let $\mathcal{A}_{y}$ and $\mathcal{A}_{z}$ denote the sufficient-decrease events for $\mathbf{y}^{k}$ and $\mathbf{z}^{k}$ appearing in \eqref{eq: Event A}. Since $\mathcal{E}_{A}^{0,r}=\mathcal{A}_{y}\cup\mathcal{A}_{z}$ and the reflection coupling gives $\{\mathbf{y}^{k}\}$ and $\{\mathbf{z}^{k}\}$ identical marginal laws, $\mathbb{P}[\mathcal{A}_{y}]=\mathbb{P}[\mathcal{A}_{z}]$. Hence,
\begin{gather*}
    \mathbb{P}[\mathcal{A}_{y}]
    =\mathbb{P}[\mathcal{A}_{z}]
    \geq\frac{1}{3}-(r^{2}+8r)\mathrm{e}^{-\rho}.
\end{gather*}
Each marginal process has the same law as \eqref{eq: NLGD with auxiliary function 1}. Taking $\rho_{\min,5}\geq\max\{\rho_{\min,3},\rho_{\min,4}\}$ proves the result.

Let
\[
    \underline{\Psi}\coloneqq\sum_{i=1}^{m}f_i^\star,
    \qquad
    D\coloneqq\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{0})-\underline{\Psi}\geq0.
\]
If $D=0$, then $\mathbf{x}^{0}$ is a global minimizer of the smooth function $\Psi_{\boldsymbol{\theta}^{0}}$, so $\nabla\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{0})=\bm{0}$ and $\nabla^{2}\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{0})\succeq0$; the claim is immediate. Hence assume $D>0$.

Given $\epsilon_g>0$ and $\rho\geq1$, let $\alpha$ be defined in \eqref{eq: parameters} and set
\begin{gather}
    \label{eq: K}
    K\coloneqq
    \left\lceil
    \frac{D}{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}\epsilon_g^{2}\alpha^{2}}
    \right\rceil
    =
    \left\lceil
    D\,\epsilon_g^{-2}\alpha^{-1}\rho^{7}
    \right\rceil .
\end{gather}
Define, for $k\geq0$,
\begin{gather*}
    \mathcal{E}_{1}^{k}\coloneqq
    \{\|\nabla\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k})\|\geq\epsilon_g\},\\
    \mathcal{E}_{2}^{k}\coloneqq
    \{\|\nabla\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k})\|<\epsilon_g,\ 
    \lambda_{\min}(\nabla^{2}\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k}))<-\epsilon_H\},\\
    \mathcal{E}_{3}^{k}\coloneqq
    \{\|\nabla\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k})\|<\epsilon_g,\ 
    \lambda_{\min}(\nabla^{2}\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k}))\geq-\epsilon_H\}.
\end{gather*}
These events form a partition for each $k$. It suffices to show that $\mathcal{E}_{3}^{k}$ occurs at least once for $k=0,\ldots,K-1$ with probability at least $1-p$. Let
\begin{gather}
    \label{eq: Event P}
    \mathcal{P}\coloneqq
    \left\{\sum_{k=0}^{K-1}
    \left(\mathbf{1}_{\mathcal{E}_{1}^{k}}+\mathbf{1}_{\mathcal{E}_{2}^{k}}\right)<K\right\}
    =
    \left\{\sum_{k=0}^{K-1}\mathbf{1}_{\mathcal{E}_{3}^{k}}\geq1\right\},
\end{gather}
and
\begin{gather*}
    \mathcal{P}_{1}\coloneqq
    \left\{
    \sum_{k=0}^{K-1}\left(\mathbf{1}_{\mathcal{E}_{1}^{k}}+\mathbf{1}_{\mathcal{E}_{2}^{k}}\right)<K
    \ \lor\
    \sum_{k=0}^{K-1}\mathbf{1}_{\mathcal{E}_{1}^{k}}<\frac{K}{2}
    \right\},\\
    \mathcal{P}_{2}\coloneqq
    \left\{
    \sum_{k=0}^{K-1}\left(\mathbf{1}_{\mathcal{E}_{1}^{k}}+\mathbf{1}_{\mathcal{E}_{2}^{k}}\right)<K
    \ \lor\
    \sum_{k=0}^{K-1}\mathbf{1}_{\mathcal{E}_{2}^{k}}<\frac{K}{2}
    \right\}.
\end{gather*}
Then
\begin{gather}
    \label{eq: P1 and P2 to P}
    \mathcal{P}_{1}\cap\mathcal{P}_{2}\subseteq\mathcal{P}.
\end{gather}

Define the noise-concentration event
\begin{gather*}
    \mathcal{N}_{K}\coloneqq
    \left\{\sum_{k=0}^{K-1}\|\mathbf{n}^{k}\|^{2}
    \leq2mn\sigma^{2}(K+\sqrt{K\rho}+\rho)\right\}.
\end{gather*}
By \eqref{eq: descent third term},
\begin{gather}
    \label{eq: global noise event}
    \mathbb{P}[\mathcal{N}_{K}]\geq1-2\mathrm{e}^{-\rho}.
\end{gather}

We first bound $\mathbb{P}[\mathcal{P}_{1}]$. On $\bar{\mathcal{P}}_{1}$, at least $K/2$ of the indices $k=0,\ldots,K-1$ satisfy $\mathcal{E}_{1}^{k}$. Hence, by \eqref{eq: descent}, on $\bar{\mathcal{P}}_{1}\cap\mathcal{N}_{K}$,
\begin{gather*}
    \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{K})
    -\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{0})
    \leq-L_{1},
\end{gather*}
where
\begin{gather*}
    L_{1}\coloneqq
    \frac{\alpha K\epsilon_g^{2}}{4}
    -mn\alpha\sigma^{2}(K+\sqrt{K\rho}+\rho).
\end{gather*}
Since $D>0$, for sufficiently large $\rho$ we have $K\geq\rho$. Using \eqref{eq: Variance} and $L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}\alpha=\rho^{-7}$,
\begin{align*}
    L_{1}
    &\geq
    \alpha K\left(\frac{\epsilon_g^{2}}{4}-3mn\sigma^{2}\right)
    =
    \frac{\alpha K\epsilon_g^{2}}{4}(1-\rho^{-7})
    \geq\frac{\alpha K\epsilon_g^{2}}{8}.
\end{align*}
Moreover, by \eqref{eq: K},
\begin{gather*}
    \frac{\alpha K\epsilon_g^{2}}{8}
    \geq\frac{D}{8L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}\alpha}
    =\frac{D\rho^{7}}{8}.
\end{gather*}
Thus, there exists $\rho_{\min,6}\geq1$ such that $L_{1}>D$ for all $\rho\geq\rho_{\min,6}$. Since $\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x})\geq\underline{\Psi}$ for all $\mathbf{x}$, the event $\bar{\mathcal{P}}_{1}\cap\mathcal{N}_{K}$ is empty. Therefore,
\begin{gather}
    \label{eq: Contradiction 1}
    \mathbb{P}[\mathcal{P}_{1}]
    \geq\mathbb{P}[\mathcal{N}_{K}]
    \geq1-2\mathrm{e}^{-\rho}.
\end{gather}

We next bound $\mathbb{P}[\mathcal{P}_{2}]$. On $\bar{\mathcal{P}}_{2}$, at least $K/2$ indices in $\{0,\ldots,K-1\}$ satisfy $\mathcal{E}_{2}^{k}$. For sufficiently large $\rho$, $r\geq\rho$ and
\begin{gather*}
    \ell_s
    \geq
    \frac{d^{2}}{4\alpha r}-6mn\alpha\sigma^{2}r.
\end{gather*}
Also, for sufficiently large $\rho$,
\[
    r\leq\frac{2\rho}{\alpha\epsilon_H}.
\]
Using \eqref{eq: Variance}, \eqref{eq: parameters}, and $\epsilon_H^{2}=\epsilon_gL_{\Psi_{\boldsymbol{\theta}^{0}}}^{H}$,
\begin{gather*}
    \frac{6mn\alpha\sigma^{2}r}{d^{2}/(8\alpha r)}
    =
    \frac{48mn\alpha^{2}\sigma^{2}r^{2}}{d^{2}}
    \leq\frac{6400}{\rho}.
\end{gather*}
Hence, there exists $\rho_{\min,7}\geq1$ such that, for all $\rho\geq\rho_{\min,7}$,
\begin{gather}
    \label{eq: ls lower bound}
    \ell_s\geq\frac{d^{2}}{8\alpha r}>0.
\end{gather}
Consequently,
\begin{gather}
    \label{eq: r/ls}
    \frac{r}{\ell_s}
    \leq\frac{8\alpha r^{2}}{d^{2}}
    \leq12800L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}\epsilon_g^{-2}\rho^{13}.
\end{gather}

Recall
\[
    q_{\rho}=\frac13-(r^{2}+8r)\mathrm{e}^{-\rho}.
\]
Since $r$ is polynomial in $\rho$ and $K/r$ grows as $\rho^{6}$ when $D>0$, there exists $\rho_{\min,8}\geq\max\{\rho_{\min,5},\rho_{\min,7}\}$ such that, for all $\rho\geq\rho_{\min,8}$,
\begin{gather}
    \label{eq: large rho block conditions}
    q_{\rho}\geq\frac14,\qquad K\geq8r,\qquad K\geq\rho.
\end{gather}

We now construct disjoint saddle blocks. Let $T_{1}$ be the first $k\in\{0,\ldots,K-r\}$ for which $\mathcal{E}_{2}^{k}$ occurs; if no such $k$ exists, set $T_{1}=K$. Recursively, if $T_j=K$, set $Z_j=1$, $\tau_j=0$, and $T_{j+1}=K$. Otherwise define
\begin{gather*}
    \mathcal{A}_{j}\coloneqq
    \left\{\exists\tau\in\{1,\ldots,r\}:~
    \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{T_j+\tau})
    -\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{T_j})
    \leq-\ell_s\right\},
\end{gather*}
\begin{gather*}
    \tau_j\coloneqq
    \begin{cases}
        \min\{\tau\in\{1,\ldots,r\}:
        \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{T_j+\tau})
        -\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{T_j})\leq-\ell_s\},
        & \mathcal{A}_j\text{ occurs},\\
        r, & \text{otherwise},
    \end{cases}
\end{gather*}
where
\begin{gather*}
    Z_j\coloneqq\mathbf{1}_{\mathcal{A}_j}.
\end{gather*}
and let $T_{j+1}$ be the first $k\in\{T_j+\tau_j,\ldots,K-r\}$ satisfying $\mathcal{E}_{2}^{k}$; if no such index exists, set $T_{j+1}=K$.

Under $\bar{\mathcal{P}}_{2}$, at most $r$ saddle indices lie in the final $r$ positions, and each selected block contains at most $r$ indices. Therefore the first
\begin{gather}
    \label{eq: saddle block number}
    M\coloneqq\left\lfloor\frac{K/2-r}{r}\right\rfloor
\end{gather}
selected blocks are genuine, and \eqref{eq: large rho block conditions} gives
\begin{gather*}
    M\geq\frac{K}{4r}.
\end{gather*}

By \eqref{eq: conditional saddle decrease}, for a genuine block,
\[
    \mathbb{E}[Z_j\mid\mathcal{H}_{T_j}]\geq q_{\rho},
\]
while for a dummy block $Z_j=1$, so the same bound holds. Set $\mu_j\coloneqq\mathbb{E}[Z_j\mid\mathcal{H}_{T_j}]$ and define the block filtration $\mathcal{B}_{0}\coloneqq\mathcal{H}_{T_1}$ and $\mathcal{B}_{j}\coloneqq\mathcal{H}_{T_{j+1}}$ for $j\geq1$. Then $Z_j$ is $\mathcal{B}_{j}$-measurable, $\mu_j$ is $\mathcal{B}_{j-1}$-measurable, and
\[
    \mathbb{E}[Z_j-\mu_j\mid\mathcal{B}_{j-1}]=0.
\]
Thus $\{Z_j-\mu_j\}_{j=1}^{M}$ is a martingale-difference sequence with increments bounded in absolute value by $1$. Therefore, by the Azuma--Hoeffding inequality,
\begin{gather}
    \label{eq: saddle block concentration}
    \mathbb{P}\left[\sum_{j=1}^{M}Z_j<\frac{q_{\rho}M}{2}\right]
    \leq
    \exp\left(-\frac{q_{\rho}^{2}M}{8}\right).
\end{gather}
Since $M\geq K/(4r)$ and $K/r$ grows as $\rho^{6}$, there exists $\rho_{\min,9}\geq\rho_{\min,8}$ such that
\begin{gather}
    \label{eq: saddle block tail}
    \exp\left(-\frac{q_{\rho}^{2}M}{8}\right)\leq\mathrm{e}^{-\rho}
\end{gather}
for all $\rho\geq\rho_{\min,9}$.

On $\bar{\mathcal{P}}_{2}$, all first $M$ blocks are genuine. On the complement of the event in \eqref{eq: saddle block concentration},
\[
    S\coloneqq\sum_{j=1}^{M}Z_j
    \geq\frac{q_{\rho}M}{2}
    \geq\frac{K}{32r}.
\]
The successful block intervals are disjoint, and each contributes an objective decrease of at least $\ell_s$. For every remaining individual iteration, the one-step estimate in the proof of Lemma \ref{lem: Decrease} gives
\[
    \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k+1})
    -\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k})
    \leq\frac{\alpha}{2}\|\mathbf{n}^{k}\|^{2}.
\]
Hence, on $\bar{\mathcal{P}}_{2}\cap\mathcal{N}_{K}$ and the complement of the event in \eqref{eq: saddle block concentration},
\begin{align}
    \label{eq: P2 total decrease}
    \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{K})
    -\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{0})
    &\leq
    -S\ell_s+\frac{\alpha}{2}\sum_{k=0}^{K-1}\|\mathbf{n}^{k}\|^{2}\nonumber\\
    &\leq
    -\frac{K\ell_s}{32r}
    +mn\alpha\sigma^{2}(K+\sqrt{K\rho}+\rho).
\end{align}

The first term dominates the initial objective gap for sufficiently large $\rho$. Indeed, by \eqref{eq: K} and \eqref{eq: r/ls},
\begin{gather*}
    \frac{K\ell_s}{32r}
    \geq
    \frac{D\rho}{409600}.
\end{gather*}
Moreover, since $K\geq\rho$ and $K\leq D/(L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}\epsilon_g^{2}\alpha^{2})+1$,
\begin{align*}
    mn\alpha\sigma^{2}(K+\sqrt{K\rho}+\rho)
    &\leq3mn\alpha\sigma^{2}K\\
    &=\frac{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}\alpha^{2}\epsilon_g^{2}}{4}K\\
    &\leq\frac{D}{4}
    +\frac{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}\alpha^{2}\epsilon_g^{2}}{4}.
\end{align*}
Since $D>0$, by increasing $\rho_{\min,9}$ if necessary, the last term is at most $D/4$, and
\begin{gather*}
    \frac{K\ell_s}{32r}
    >
    D+mn\alpha\sigma^{2}(K+\sqrt{K\rho}+\rho).
\end{gather*}
Thus \eqref{eq: P2 total decrease} would imply
\[
    \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{K})<\underline{\Psi},
\]
contradicting the definition of $\underline{\Psi}$. Hence
\[
    \bar{\mathcal{P}}_{2}
    \subseteq
    \mathcal{N}_{K}^{c}
    \cup
    \left\{\sum_{j=1}^{M}Z_j<\frac{q_{\rho}M}{2}\right\}.
\]
Using \eqref{eq: global noise event}, \eqref{eq: saddle block tail}, and the union bound,
\begin{gather}
    \label{eq: Contradiction 2}
    \mathbb{P}[\mathcal{P}_{2}]
    \geq1-3\mathrm{e}^{-\rho}.
\end{gather}

Combining \eqref{eq: Contradiction 1}, \eqref{eq: Contradiction 2}, and \eqref{eq: P1 and P2 to P} gives
\begin{gather*}
    \mathbb{P}[\mathcal{P}]
    \geq1-5\mathrm{e}^{-\rho}.
\end{gather*}
Hence there exists $\rho_{\min,10}\geq\rho_{\min,9}$ such that for all $\rho\geq\rho_{\min,10}$,
\begin{multline}
    \label{eq: Approximately second order staionarity}
    \mathbb{P}\Big[\exists k\in[0,K]:~
    \|\nabla\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k})\|\leq\epsilon_g
    \ \land\
    \lambda_{\min}(\nabla^{2}\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k}))\geq-\epsilon_H\Big]\\
    \geq1-5\mathrm{e}^{-\rho}
    \geq1-\mathrm{e}^{-\rho/2}.
\end{multline}

Finally, \eqref{eq: Approximate second order} follows by choosing
\begin{gather*}
    \bar{\alpha}
    =
    \min\left\{
    \frac{(\rho_{\min,11})^{-7}}{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}},
    \frac{2\ln(1/p)}{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}},
    \frac{1}{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}[2\ln(1/p)]^{7}}
    \right\},
\end{gather*}
where
\begin{gather*}
    \rho_{\min,11}
    \geq
    \max\{\rho_{\min,6},\rho_{\min,8},\rho_{\min,9},\rho_{\min,10}\}.
\end{gather*}
For any $0<\alpha\leq\bar{\alpha}$, let
\[
    \rho
    =
    \left(\frac{1}{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}\alpha}\right)^{1/7}.
\]
Then $\rho\geq\rho_{\min,11}$ and $\rho\geq2\ln(1/p)$. Hence
\[
    1-\mathrm{e}^{-\rho/2}\geq1-p,
\]
which proves \eqref{eq: Approximate second order}.

\begin{gather}
        \label{eq: large rho block conditions}
        q_{\rho}\geq\frac14,\qquad K\geq8r,\qquad K\geq\rho.
    \end{gather}

By \eqref{eq: Approximate second order} in
Proposition~\ref{pro: Approximate second order}, there exists
\begin{gather*}
    \bar{\alpha}
    \le
    \min\left\{
    \frac{1}{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}},
    -\frac{2\ln(p)}{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}}
    \right\}
\end{gather*}
such that for any step-size $\alpha \le \bar{\alpha}$,
with $K$ as per \eqref{eq: Iteration}, and initial condition
satisfying $\mathbf{x}^{0}=\bm{0}$, it follows that after
$K$ iterations of \eqref{eq: NLGD with auxiliary function},
\begin{align*}
    \mathbb{P}\Bigg[
    \exists k\in[0,K],~
    \|\nabla\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k})\|
    \le\epsilon_{g}
    ~\land~
    \lambda_{\min}
    \left(
    \nabla^{2}\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k})
    \right)
    \ge-\epsilon_{H}
    \Bigg]
    \ge 1-p.
\end{align*}

By Proposition~\ref{pro: NGD interpretation},
\[
    \boldsymbol{\theta}^{k}
    =
    \boldsymbol{\theta}^{0}
    +
    \sqrt{\hat{\mathbf{L}}}\mathbf{x}^{k}.
\]
Since $\boldsymbol{\theta}^{0}$ is feasible and
\[
    (\bm{1}_{m}^{\top}\otimes\mathbf{I}_{n})
    \sqrt{\hat{\mathbf{L}}}
    =
    \bm{0}^{\top},
\]
it follows that, for every $k\ge0$,
\begin{gather*}
    (\bm{1}_{m}^{\top}\otimes\mathbf{I}_{n})
    \boldsymbol{\theta}^{k} =
    (\bm{1}_{m}^{\top}\otimes\mathbf{I}_{n})
    \left(
    \boldsymbol{\theta}^{0}
    +
    \sqrt{\hat{\mathbf{L}}}\mathbf{x}^{k}
    \right) =
    (\bm{1}_{m}^{\top}\otimes\mathbf{I}_{n})
    \boldsymbol{\theta}^{0} =
    \bm{r}.
\end{gather*}

Then, by Proposition~\ref{pro: Second order relations}
and Proposition~\ref{pro: NGD interpretation},
after $K$ iterations of~\eqref{eq: NLGD},
\begin{multline*}
    \mathbb{P}\Bigg[
    \exists k\in[0,K],~
    \|\sqrt{\hat{\mathbf{L}}}\cdot
    \nabla F(\boldsymbol{\theta}^{k})\|
    \le\epsilon_{g}\\
    \land~
    \forall\,\mathbf{d}\in\mathcal{T},~
    \mathbf{d}^{\top}
    \nabla^{2}F(\boldsymbol{\theta}^{k})
    \mathbf{d}
    \ge
    -
    \frac{\epsilon_{H}}
    {\lambda_{\min}^{+}(\mathbf{L})}
    \|\mathbf{d}\|^{2}
    ~\land~
    (\bm{1}_{m}^{\top}\otimes\mathbf{I}_{n})
    \boldsymbol{\theta}^{k}
    =
    \bm{r}
    \Bigg]
    \ge 1-p,
\end{multline*}
as claimed.

Each agent $i$ controls a portfolio vector $\boldsymbol{\theta}_{i} \in \mathbb{R}^{n}$, and a typical local objective has the form
\begin{gather*}
    f_{i}(\boldsymbol{\theta}_{i})
    = -\mu_{i}^{\top} \boldsymbol{\theta}_{i}
    + \lambda_{i} \boldsymbol{\theta}_{i}^{\top} \Sigma_{i} \boldsymbol{\theta}_{i}
    + \gamma_{i} \log(1 + \|\boldsymbol{\theta}_{i}\|^{2}),
\end{gather*}
where $\mu_{i} \in \mathbb{R}^{n}$ denotes expected returns, $\Sigma_{i} \in \mathbb{R}^{n \times n}$ is a covariance matrix, and $\gamma_i > 0$ weights the non-convex regularizer.
